import{_ as o,c as e,o as t,ag as i}from"./chunks/framework.DPDPlp3K.js";const d=JSON.parse('{"title":"工程化","description":"","frontmatter":{},"headers":[],"relativePath":"front-end/build-tools.md","filePath":"front-end/build-tools.md","lastUpdated":1741677671000}'),r={name:"front-end/build-tools.md"};function s(n,l,p,g,a,u){return t(),e("div",null,l[0]||(l[0]=[i('<h1 id="工程化" tabindex="-1">工程化 <a class="header-anchor" href="#工程化" aria-label="Permalink to &quot;工程化&quot;">​</a></h1><h2 id="webpack" tabindex="-1">Webpack <a class="header-anchor" href="#webpack" aria-label="Permalink to &quot;Webpack&quot;">​</a></h2><ol><li><p><strong>Webpack 是什么？它的核心功能是什么？</strong></p><ul><li>Webpack 是模块化打包工具，将分散的 JS、CSS、图片等资源视为模块，分析依赖关系并打包成静态文件。</li><li><strong>核心功能</strong>：代码编译、依赖分析、代码分割、资源优化。</li></ul></li><li><p><strong>Webpack 的核心概念是什么？</strong></p><ul><li><strong>入口（Entry）</strong>：指示 Webpack 应该从哪个文件开始构建依赖图（可以指定一个或多个入口文件）。</li><li><strong>输出（Output）</strong>：输出指示 Webpack 在哪里输出打包文件。</li><li><strong>加载器（Loaders）</strong>：允许 Webpack 处理非 JavaScript 文件（如 CSS、图片、字体等）。</li><li><strong>插件（Plugins）</strong>：用于扩展 Webpack 功能（如：优化资源、压缩代码、添加环境变量等）。</li><li><strong>模式（Mode）</strong>：用于指定 Webpack 的构建模式，可以是开发模式（development）、生产模式（production）或其他。</li></ul></li><li><p><strong>Loader 和 Plugin 的作用及区别是什么？</strong></p><ul><li><strong>Loader</strong>：处理非 JS 文件（如转换 SASS/LESS 为 CSS、转换 ES6/ES7 为 ES5 等），按顺序链式调用。</li><li><strong>Plugin</strong>：扩展 Webpack 功能（如生成 HTML 文件，代码压缩、资源优化、环境变量注入等），通过钩子影响打包全流程。</li></ul><blockquote><p><strong>记忆点</strong>：Loader 处理文件，Plugin 扩展流程。</p></blockquote></li><li><p><strong>Webpack 如何实现代码分割（Code Splitting）？</strong></p><ul><li>入口分割：配置多入口（<code>entry: { a: &#39;a.js&#39;, b: &#39;b.js&#39; }</code>）。</li><li>动态导入：使用 <code>import()</code> 语法，生成独立 chunk。</li><li>配置 <code>optimization.splitChunks</code> 提取公共代码。</li></ul><blockquote><p><strong>记忆点</strong>：多入口 + 动态导入 + splitChunks 优化。</p></blockquote></li><li><p><strong>Webpack 的 Tree Shaking 如何生效？需要满足哪些条件？</strong></p><ul><li>基于 ES Module 静态语法（<code>import/export</code>），删除未使用代码。</li><li><strong>条件</strong>：生产模式（<code>mode: &#39;production&#39;</code>）、禁用 Babel 的 ESM 转换、<code>package.json</code> 中标记 <code>sideEffects: false</code>。</li></ul><blockquote><p><strong>记忆点</strong>：ESM 语法 + 生产模式 + sideEffects 标记。</p></blockquote></li><li><p><strong>Webpack 构建性能优化有哪些常见手段？</strong></p><ul><li><strong>Tree Shaking</strong>: 使用 ES6 模块语法并启用 Tree Shaking 来消除未使用的代码，减小打包体积。</li><li><strong>代码拆分 (Code Splitting)</strong>: 将应用程序拆分为多个 bundle，并实现按需加载，以减少初始加载时需要下载的资源量，加快页面加载速度。</li><li><strong>使用 CDN</strong>: 将第三方依赖库（如 React、Vue、jQuery 等）从打包中移除，并通过 CDN 引入，减小打包体积并加速页面加载。</li><li><strong>压缩资源</strong>: 使用 Webpack 的压缩插件（如 uglifyjs-webpack-plugin、terser-webpack-plugin 等）来压缩 JavaScript 代码、CSS 代码等，减小文件体积。</li><li><strong>优化图片</strong>: 使用 image-webpack-loader 或者 url-loader 来优化图片资源，压缩图片并将小图片转换为 base64 格式，减少 HTTP 请求并加快加载速度。</li><li><strong>提取公共代码</strong>: 使用 Webpack 的 SplitChunksPlugin 来提取公共模块，减少重复代码，并将其打包到单独的文件中，以便浏览器缓存和复用。</li><li><strong>缓存优化</strong>: 使用 Webpack 的持久化缓存（persistent caching）功能，利用构建结果的 hash 值来标识构建结果的变化，从而提高构建效率。</li><li><strong>多进程构建</strong>: 使用 webpack-parallel-uglify-plugin、thread-loader 等插件来启用多进程构建，利用多核 CPU 提高构建速度。</li><li><strong>减少不必要的 Loader</strong>: 只加载必要的 Loader，避免加载过多的 Loader，以减少构建时间。</li><li><strong>使用 DllPlugin</strong>: 使用 webpack.DllPlugin 来预先编译第三方库，以减少每次构建时的依赖分析时间。</li><li><strong>减少文件搜索范围</strong>: 使用 resolve.modules、resolve.extensions、resolve.alias 等配置来减少文件搜索范围，提高构建速度。</li></ul></li></ol><h2 id="vite" tabindex="-1">Vite <a class="header-anchor" href="#vite" aria-label="Permalink to &quot;Vite&quot;">​</a></h2><ol><li><p><strong>Vite 是什么？它解决了什么问题？</strong></p><ul><li>Vite 是新一代前端构建工具，解决传统打包工具（如 Webpack）开发环境冷启动慢、热更新效率低的问题。</li><li><strong>核心思想</strong>：开发环境基于浏览器原生 ESM，生产环境用 Rollup 打包。</li></ul></li><li><p><strong>Vite 为什么开发环境比 Webpack 快？</strong></p><ul><li><strong>无打包</strong>：浏览器直接加载 ESM 模块。</li><li><strong>按需编译</strong>：只编译在浏览器中实际使用的代码。</li><li><strong>预构建</strong>：用 esbuild 将 CommonJS 依赖转换为 ESM。</li><li><strong>并行构建</strong>：多个进程中同时编译代码。</li><li><strong>缓存</strong>：依赖预构建结果缓存，避免重复编译。</li></ul><blockquote><p><strong>记忆点</strong>：原生 ESM + esbuild 预构建 + 缓存机制。</p></blockquote></li><li><p><strong>Vite 的热更新（HMR）为什么高效？</strong></p><ul><li>基于浏览器原生 ESM，仅更新修改的模块，无需重建依赖图。</li><li>服务端通过 <code>WebSocket</code> 推送更新信息，客户端精准替换模块。</li></ul><blockquote><p><strong>记忆点</strong>：精准模块替换 + WebSocket 推送。</p></blockquote></li><li><p><strong>Vite 如何处理 TypeScript 和 CSS 预处理器？</strong></p><ul><li><strong>TypeScript</strong>：内置支持，直接编译（无需额外配置）。</li><li><strong>CSS 预处理器</strong>：安装对应工具（如 sass/less/stylus）即可直接使用。</li></ul><blockquote><p><strong>记忆点</strong>：TS 开箱即用，CSS 预处理需安装工具。</p></blockquote></li><li><p><strong>Vite 生产环境打包为什么选择 Rollup？</strong></p><ul><li>Rollup 的 Tree Shaking 更彻底，输出代码更小。</li><li>更适合生成符合 ESM 标准的库或应用。</li></ul><blockquote><p><strong>记忆点</strong>：Rollup 更小的输出 + 更严格的 ESM 支持。</p></blockquote></li></ol><h2 id="rollup" tabindex="-1">Rollup <a class="header-anchor" href="#rollup" aria-label="Permalink to &quot;Rollup&quot;">​</a></h2><ol><li><p><strong>Rollup 是什么？它的设计目标是什么？</strong></p><ul><li>Rollup 是专注于 JavaScript 库打包的工具，设计目标是生成更小、更高效的代码，尤其适合库的发布。<br><strong>核心优势</strong>：Tree Shaking 彻底、输出格式灵活（ESM/UMD 等）。</li></ul></li><li><p><strong>Rollup 和 Webpack 的主要区别是什么？</strong></p><ul><li><strong>Rollup</strong>：适合库，输出扁平化代码，Tree Shaking 更彻底。</li><li><strong>Webpack</strong>：适合应用，支持代码分割、动态加载等复杂功能。</li></ul></li><li><p><strong>Rollup 如何处理 CommonJS 模块？</strong></p><ul><li>需安装 <code>@rollup/plugin-commonjs</code> 插件转换 CommonJS 为 ESM。</li><li>配合 <code>@rollup/plugin-node-resolve</code> 解析 <code>node_modules</code> 依赖。</li></ul><blockquote><p><strong>记忆点</strong>：CommonJS 需插件转换，Node 模块需解析插件。</p></blockquote></li><li><p><strong>为什么 Rollup 的 Tree Shaking 更高效？</strong></p><ul><li>基于 ESM 静态分析，删除所有未使用的代码。</li><li>输出结果无 Webpack 的模块包装代码，结构更扁平。</li></ul><blockquote><p><strong>记忆点</strong>：ESM 静态分析 + 无冗余代码。</p></blockquote></li><li><p><strong>Rollup 如何实现代码分割（Code Splitting）？</strong></p><ul><li>配置 <code>output.dir</code> 代替 <code>output.file</code>，输出多文件。</li><li>使用动态导入（<code>import()</code>）自动分割代码。</li></ul><blockquote><p><strong>记忆点</strong>：多文件输出 + 动态导入自动分割。</p></blockquote></li></ol><h2 id="gulp" tabindex="-1">Gulp <a class="header-anchor" href="#gulp" aria-label="Permalink to &quot;Gulp&quot;">​</a></h2><ol><li><p><strong>Gulp 是什么？它适用于什么场景？</strong></p><ul><li>Gulp 是基于流的自动化任务运行器，适用于文件转换、压缩、打包等重复性任务。</li><li><strong>典型场景</strong>：静态资源处理（如压缩图片、编译 SASS）。</li></ul></li><li><p><strong>Gulp 的流（Stream）处理机制是什么？</strong></p><ul><li>通过 <code>gulp.src()</code> 读取文件生成 Vinyl 虚拟文件流。</li><li>使用 <code>pipe()</code> 连接插件处理文件（如 <code>gulp-sass</code> 编译 CSS）。</li><li>最终通过 <code>gulp.dest()</code> 输出到磁盘。</li></ul><blockquote><p><strong>记忆点</strong>：src → pipe 处理链 → dest 输出。</p></blockquote></li><li><p><strong>如何用 Gulp 监听文件变化并自动执行任务？</strong></p><ul><li>使用 <code>gulp.watch()</code> 监听文件变化。</li><li>示例：<code>gulp.watch(&#39;src/*.scss&#39;, gulp.series(&#39;compile-sass&#39;))</code>。</li></ul></li><li><p><strong>Gulp 如何处理任务间的依赖关系？</strong></p><ul><li>使用 <code>gulp.series()</code> 顺序执行任务（如先清理再构建）。</li><li>使用 <code>gulp.parallel()</code> 并行执行任务（如同时压缩 JS 和 CSS）。</li></ul><blockquote><p><strong>记忆点</strong>：series 串行，parallel 并行。</p></blockquote></li></ol><h2 id="tree-shaking" tabindex="-1">Tree Shaking <a class="header-anchor" href="#tree-shaking" aria-label="Permalink to &quot;Tree Shaking&quot;">​</a></h2><ol><li><p><strong>Tree Shaking 是什么？它的设计目标是什么？</strong></p><ul><li>Tree Shaking 是消除 JavaScript 中未使用代码的优化技术，通过静态分析模块依赖关系，删除未被引用的代码（“死代码”）。</li><li><strong>目标</strong>：减少代码体积，提升执行效率。</li></ul><blockquote><p><strong>记忆点</strong>：静态分析依赖，删除无用代码。</p></blockquote></li><li><p><strong>Tree Shaking 的实现原理是什么？</strong></p><ul><li><strong>依赖 ES Module</strong>：利用 <code>import/export</code> 的静态语法特性（编译时分析依赖）。</li><li><strong>标记未引用代码</strong>：构建工具（如 Webpack/Rollup）标记未被使用的导出。</li><li><strong>删除阶段</strong>：在压缩阶段（如 Terser）移除标记的代码。</li></ul><blockquote><p><strong>记忆点</strong>：ESM 静态分析 → 标记 → 压缩删除。</p></blockquote></li><li><p><strong>如何确保 Tree Shaking 生效？需要满足哪些条件？</strong></p><ul><li><strong>代码层面</strong>：使用 ES Module（<code>import/export</code>），避免 CommonJS。</li><li><strong>工具配置</strong>： <ul><li>Webpack：<code>mode: &#39;production&#39;</code>，<code>optimization.usedExports: true</code>。</li><li>Rollup：默认开启，无需额外配置。</li></ul></li><li><strong>库标记</strong>：在 <code>package.json</code> 中设置 <code>sideEffects: false</code>（或指定副作用文件）。</li></ul><blockquote><p><strong>记忆点</strong>：ESM 语法 + 生产模式 + sideEffects 标记。</p></blockquote></li></ol>',11)]))}const k=o(r,[["render",s]]);export{d as __pageData,k as default};
